parsed_data = []
for line in raw_data.strip().split('\n'):
    parts = line.strip().split()
    if len(parts) >= 15:
        year = int(parts[0])
        annual_temp = float(parts[-1])
        parsed_data.append({"year": year, "annual_temp": annual_temp})

with open("frontend/assets/india_temperature_1901_2025.json", "w") as f:
    json.dump(parsed_data, f, indent=2)

print(f"Parsed {len(parsed_data)} records to JSON.")
